/**
 * imm — immutable-update helpers for nested state, path-based.
 *
 * All operations are persistent: they never mutate their inputs and they
 * share unchanged branches, so untouched subtrees keep reference equality.
 */

/** A path mixes plain object keys (string) and array indices (number). */
export type Path = readonly (string | number)[];

type Container = Record<string | number, unknown> | unknown[];

function isContainer(v: unknown): v is Container {
  return typeof v === "object" && v !== null;
}

function getChild(container: unknown, key: string | number): unknown {
  if (!isContainer(container)) return undefined;
  return (container as Container)[key];
}

function hasKey(container: unknown, key: string | number): boolean {
  if (Array.isArray(container)) {
    return typeof key === "number" && key >= 0 && key < container.length;
  }
  return isContainer(container) && key in container;
}

/**
 * Shallow-copy `container` with `key` set to `value`.
 * Vivifies when `container` is nullish/primitive; the kind of container
 * created is irrelevant here (the caller decides via the next segment),
 * an object is the safe default for keyed writes.
 */
function cloneWith(
  container: unknown,
  key: string | number,
  value: unknown,
): Container {
  if (Array.isArray(container) && typeof key === "number") {
    const copy = container.slice();
    copy[key] = value;
    return copy;
  }
  if (isContainer(container)) {
    const copy = Array.isArray(container)
      ? ({ ...(container as unknown as Record<string, unknown>) } as Container)
      : { ...(container as Record<string, unknown>) };
    (copy as Record<string | number, unknown>)[key] = value;
    return copy;
  }
  // Auto-vivification of a missing/primitive node.
  return { [key]: value };
}

/** A fresh intermediate container: array if the next segment is a number. */
function vivify(nextSegment: string | number | undefined): Container {
  return typeof nextSegment === "number" ? [] : {};
}

/** Read the value at `path`; `undefined` when any step is missing. */
export function getIn<T>(obj: T, path: Path): unknown {
  let current: unknown = obj;
  for (const key of path) {
    if (!hasKey(current, key)) return undefined;
    current = getChild(current, key);
  }
  return current;
}

function setAt(current: unknown, path: Path, depth: number, value: unknown): unknown {
  const key = path[depth]!;

  if (depth === path.length - 1) {
    if (hasKey(current, key) && Object.is(getChild(current, key), value)) {
      return current; // no-op: identical value, keep identity
    }
    return cloneWith(current, key, value);
  }

  const child = getChild(current, key);
  const target =
    isContainer(child) ? child : vivify(typeof key === "number" && false ? key : path[depth + 1]);
  const newChild = setAt(target, path, depth + 1, value);
  if (newChild === child) return current;
  return cloneWith(current, key, newChild);
}

/** Return `obj` with the value at `path` replaced by `value`. */
export function setIn<T>(obj: T, path: Path, value: unknown): T {
  if (path.length === 0) {
    return (Object.is(obj, value) ? obj : value) as T;
  }
  return setAt(obj, path, 0, value) as T;
}

/** Return `obj` with the value at `path` replaced by `fn(oldValue)`. */
export function updateIn<T>(
  obj: T,
  path: Path,
  fn: (oldValue: any) => unknown,
): T {
  return setIn(obj, path, fn(getIn(obj, path)));
}

function removeAt(current: unknown, path: Path, depth: number): unknown {
  if (!isContainer(current)) return current;

  const key = path[depth]!;

  if (depth === path.length - 1) {
    if (!hasKey(current, key)) return current; // nothing to remove: keep identity
    if (Array.isArray(current) && typeof key === "number") {
      const copy = current.slice();
      copy.splice(key, 1); // splice, don't leave a hole
      return copy;
    }
    const copy: Record<string | number, unknown> = { ...(current as Record<string, unknown>) };
    delete copy[key];
    return copy;
  }

  const child = getChild(current, key);
  const newChild = removeAt(child, path, depth + 1);
  if (newChild === child) return current;
  return cloneWith(current, key, newChild);
}

/** Return `obj` without the value at `path` (arrays splice, no holes). */
export function removeIn<T>(obj: T, path: Path): T {
  if (path.length === 0) return undefined as unknown as T;
  return removeAt(obj, path, 0) as T;
}

// ---------------------------------------------------------------------------
// Best-effort static resolution of getIn's return type along literal paths.
// Falls back to `unknown` whenever the path cannot be resolved statically.
// ---------------------------------------------------------------------------

export type GetInResult<T, P extends Path> = P extends readonly []
  ? T
  : P extends readonly [infer K, ...infer Rest]
    ? K extends keyof NonNullable<T>
      ? GetInResult<NonNullable<T>[K], Rest>
      : unknown
    : unknown;

