import { describe, expect, it } from "vitest";
import { getIn, removeIn, setIn, updateIn, type Path } from "../src/index.js";

interface Address {
  street: string;
  zip: string;
}

interface Person {
  name: string;
  address: Address;
  tags: string[];
}

const alice: Person = {
  name: "Alice",
  address: { street: "1 Main St", zip: "00001" },
  tags: ["admin", "user", "beta"],
};

describe("getIn", () => {
  it("reads through nested objects and arrays", () => {
    expect(getIn(alice, ["address", "street"])).toBe("1 Main St");
    expect(getIn(alice, ["tags", 1])).toBe("user");
  });

  it("returns undefined for missing paths without throwing", () => {
    expect(getIn(alice, ["nope", "deeper"])).toBeUndefined();
    expect(getIn(null as unknown as Person, ["a", 0])).toBeUndefined();
  });
});

describe("setIn — structural sharing", () => {
  it("preserves reference equality of untouched branches", () => {
    const next = setIn(alice, ["address", "zip"], "99999");
    expect(next).not.toBe(alice);
    expect(next.address).not.toBe(alice.address); // changed branch is new
    expect(next.tags).toBe(alice.tags); // untouched sibling: same ref
    expect((next as typeof alice).name === alice.name).toBe(true);
  });

  it("shares the whole root when only an array element changes", () => {
    const next = setIn(alice, ["tags", 2], "gamma");
    expect(next).not.toBe(alice);
    expect(next.tags).not.toBe(alice.tags);
    expect(next.tags[0]).toBe("admin");
    expect(next.address).toBe(alice.address); // object branch untouched
    expect(next.name).toBe(alice.name);
  });

  it("does not mutate the original at any depth", () => {
    const frozen = Object.freeze(structuredClone(alice));
    const next = setIn(frozen, ["tags", 0], "owner");
    expect(next).not.toBe(frozen);
    expect(frozen.tags[0]).toBe("admin");
    expect(next.tags[0]).toBe("owner");
  });
});

describe("setIn — auto-vivification", () => {
  it("creates intermediate objects keyed by strings", () => {
    const out = setIn({} as Record<string, unknown>, ["a", "b"], 42);
    expect(out).toEqual({ a: { b: 42 } });
  });

  it("creates intermediate arrays when the next segment is a number", () => {
    const out = setIn({} as Record<string, unknown>, ["a", 0], "first");
    expect(Array.isArray((out as any).a)).toBe(true);
    expect((out as any).a[0]).toBe("first");
  });

  it("vivifies deeply with mixed containers from a nullish root", () => {
    const out = setIn(undefined as unknown as Record<string, unknown>, [
      "users",
      1,
      "profile",
      "nick",
    ], "zed");
    expect(out).toEqual({ users: [undefined, { profile: { nick: "zed" } }] });
    expect(Array.isArray((out as any).users)).toBe(true);
    expect(typeof (out as any).users[1]).toBe("object");
  });

  it("vivifies array-of-objects chains", () => {
    const out = setIn({ list: [] }, ["list", 3, "x"], true);
    expect(Array.isArray((out as any).list)).toBe(true);
    expect((out as any).list[3]).toEqual({ x: true });
  });
});

describe("setIn — no-op identity case", () => {
  it("returns the original root unchanged (Object.is) for identical values", () => {
    const next = setIn(alice, ["address", "street"], "1 Main St");
    expect(next).toBe(alice);

    const arrNext = setIn(alice, ["tags", 1], "user");
    expect(arrNext).toBe(alice);

    const deepNewBranch = setIn({ a: { b: { c: 7 } } }, ["a", "b", "c"], 7);
    expect(deepNewBranch).toBe(deepNewBranch && undefined ? null : null) ?? undefined;
    // stronger form:
    const src = { a: { b: { c: 7 } } };
    expect(setIn(src, ["a", "b", "c"], 7)).toBe(src);
  });

  it("uses Object.is semantics (NaN equals NaN)", () => {
    const src = { n: NaN };
